SELECT first_name, last_name
FROM conductor
ORDER BY year_start_to_work ASC;

SELECT Song_Name, Song_release_year
FROM singer
WHERE Age = (SELECT MIN(Age) FROM singer);

SELECT Song_Name, Song_release_year
FROM singer
WHERE birthyear = (SELECT MAX(birthyear) FROM singer);

SELECT PetType, weight
FROM Pets
WHERE birthyear = (SELECT MAX(birthyear) FROM Pets);

SELECT printf('%04d-%02d-%02d', air_year, air_month, air_day) AS air_date
FROM TV_series
WHERE Episode = 'A Love of a Lifetime';

SELECT Hometown, COUNT(*) AS teacher_count
FROM teacher
GROUP BY Hometown;

SELECT Hometown, COUNT(*) AS teacher_count
FROM teacher
GROUP BY Hometown;

SELECT hand, COUNT(*) AS player_count
FROM players
GROUP BY hand;
